/// `FROG_NUMFROGS` (`Common/frogger.h:97`): characters per frog bank group.
pub const FROG_NUMFROGS: i32 = crate::frogger::FROG_NUMFROGS as i32;
/// `LEVELID_FRONTEND1` / `LEVELID_FRONTEND4` (`layout.h`).
pub const LEVELID_FRONTEND1: u32 = 0;
pub const LEVELID_FRONTEND4: u32 = 3;
pub use crate::frogger::FROG_FROGGER;

/// Globals of `layout.c` used by level loading.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub struct LayoutState {
    /// `worldVisualData[MAX_WORLDS]` (runtime copy of `origWorldVisualData`).
    pub world_visual_data: [WorldVisualData; MAX_WORLDS],
    /// `numLevelsPlayed`.
    pub num_levels_played: i32,
    /// `loadingLevel`.
    pub loading_level: bool,
}

impl Default for LayoutState {
    fn default() -> Self {
        LayoutState { world_visual_data: ORIG_WORLD_VISUAL_DATA, num_levels_played: 0, loading_level: false }
    }
}

/// Level files parsed by `InitLevel` and kept for later stages (entity creation by
/// `memload`, script execution by `event`/`script`).
#[derive(Clone, Debug, Default)]
pub struct LevelFiles {
    /// `MAPS\ENTITY-w-l.DAT` (None: missing or rejected version).
    pub entities: Option<Entities>,
    /// `MAPS\SCRIPT-w-l.FEV` (None: missing; most levels have one).
    pub script: Option<Script>,
    /// `MAPS\SFXANIMwl.SAM` records (installed into `general.sfx_anim_map`).
    pub sfx_mapping: Vec<SfxMapping>,
}

/// What the renderer has to load for a level (`LoadTextureBank`/`LoadObjectBank`
/// calls of `InitLevel`, in call order).
#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub struct LevelAssets {
    /// `textures\<name>.fla` files.
    pub texture_banks: Vec<String>,
    /// `objects\<name>.dll` files that were found and loaded.
    pub object_banks: Vec<String>,
    /// Object bank files that were requested but absent (the original only logs).
    pub missing_object_banks: Vec<String>,
    pub collision_file: String,
    pub scenics_file: String,
    /// `CreateActor("world.obe")` → `ConvertActorToLandscape` (renderer); whether the
    /// loaded banks contain the landscape model.
    pub has_world_model: bool,
}

/// `MAPS\ENTITY-%d-%d.DAT` (`LoadLevelEntities`, Common/map.c).
pub fn entity_file_name(world_id: u32, level_id: u32) -> String {
    format!("MAPS\\ENTITY-{}-{}.DAT", world_id as i32, level_id as i32)
}

/// `MAPS\SCRIPT-%d-%d.FEV` (`LoadLevelScript`, Common/script.c:1351).
pub fn script_file_name(world_id: u32, level_id: u32) -> String {
    format!("MAPS\\SCRIPT-{}-{}.FEV", world_id as i32, level_id as i32)
}

impl Game {
    /// Port of the bank-loading part of `LoadVisualBanksForWorld` (Common/layout.c:560).
    pub fn load_visual_banks_for_world(&mut self, world_id: u32, level_id: u32, data: &dyn DataSource, out: &mut LevelAssets) -> Result<(), String> {
        let wvd = self.layout.world_visual_data[world_id as usize];
        let obj_bank_to_use = wvd.master_object_bank as i32;
        let tex_bank_to_use = wvd.master_texture_bank as i32;

        let mut load_obj = |g: &mut Game, bank: i32| -> Result<(), String> {
            match g.load_object_bank(bank, data)? {
                BankLoad::Loaded(f) => out.object_banks.push(f),
                BankLoad::Missing(f) => {
                    g.effects.push(Effect::Log { text: format!("Unable to load object bank {f}") });
                    out.missing_object_banks.push(f);
                }
                BankLoad::NoFile => g.effects.push(Effect::Log { text: format!("Didn't load object bank '{bank}'") }),
            }
            Ok(())
        };

        // Contains frogger and froglet - probably quite important
        load_obj(self, INGAMEGENERIC_OBJ_BANK)?;

        // Load multiple frogs for multiplayer modes
        for i in 0..self.frogger.num_frogs.max(0) as usize {
            let multi = (self.game_state.multi != crate::define::SINGLEPLAYER) as i32;
            let bank = FROGGER_OBJ_BANK + self.frogger.player[i].character as i32 + multi * FROG_NUMFROGS;
            load_obj(self, bank)?;
        }

        if let Some(f) = texture_bank_file(tex_bank_to_use) {
            out.texture_banks.push(f);
        }
        load_obj(self, obj_bank_to_use)?;

        let lvd = &wvd.level_visual_data[level_id as usize];
        if lvd.coll_bank > -1 && lvd.object_bank_to_use > 0 {
            load_obj(self, lvd.object_bank_to_use)?;
        }

        out.has_world_model = self.models.find_object("world.obe").is_some();
        Ok(())
    }

    /// Port of `FreeAllLists` (Common/layout.c:1034) for the state ported so far.
    pub fn free_all_lists(&mut self) {
        // TODO(port): StopSong, FreeAmbientSoundList (audio),
        // FreeSpecFXList, FreeMultiplayer, FreeParticleList,
        // overlay/sprite lists (later waves).
        // ResetBabies runs after FreeMap in the original; `numBabies` (kept in `map` here)
        // is not cleared by FreeMap, so reset with the old count first.
        self.reset_babies();
        self.map = Default::default(); // FreeMap, FreeEntityBank, FreeScenic
        self.free_ambient_sound_list(); // ambient: FreeAmbientSoundList
        self.pcaudio.init_sample_list(); // ambient: FreeSampleList
        self.general.sfx_anim_map.clear(); // FreeSampleList
        self.general.ambient_tile_sfx.clear();
        self.free_trigger_list(); // wave D
        self.free_enemy_linked_list();
        self.free_platform_linked_list();
        self.path.free_path_list();
        self.free_trans_camera_list(); // wave D
        self.free_level_script(); // wave D
        self.free_tongues();
        self.free_spec_fx_list(); // wave E
        self.particle.free_particle_list(); // wave E
        if self.game_state.multi != crate::define::SINGLEPLAYER {
            self.free_multiplayer();
        }
        self.free_garib_list();
        self.level_files = LevelFiles::default();
        self.free_actor_list();
        self.models.clear(); // FreeAllObjectBanks

        // wave E: FreeTextOverlayLinkedList, FreeSpriteOverlayLinkedList, FreeSpriteList,
        // FreeProcTextures; then InitTextOverlayLinkedList(400 / 40), InitSpriteOverlayLinkedList.
        self.textover.free_text_overlay_linked_list();
        self.overlays.free_sprite_overlay_linked_list();
        self.sprite.free_sprite_list();
        self.free_proc_textures();
        let n = if self.game_state.mode == crate::define::mode::FRONTEND_MODE { 400 } else { 40 };
        self.textover.init_text_overlay_linked_list(n);
        self.overlays.init_sprite_overlay_linked_list();
    }

    /// The data half of `InitLevel` (Common/layout.c:670): frees the previous level,
    /// loads collision, scenics, object banks (model table), creates scenic actors,
    /// parses the entity file, script and sfx mapping. Returns the bank files the
    /// renderer must load. `world`/`level` index `worldVisualData`.
    pub fn load_level(&mut self, world: u32, level: u32, data: &dyn DataSource) -> Result<LevelAssets, String> {
        if world as usize >= MAX_WORLDS || level as usize >= MAX_LEVELS {
            return Err(format!("no level {world}-{level}"));
        }
        let mut out = LevelAssets::default();

        self.layout.num_levels_played += 1;
        self.frogger.player[0].world_num = world as u8;
        self.frogger.player[0].level_num = level as u8;
        if world == worldid::FRONTEND && level == LEVELID_FRONTEND1 {
            self.frogger.player[0].character = FROG_FROGGER;
        }

        self.load_language(data); // wave E: gameTextInit (once)
        self.layout.loading_level = true;
        self.free_all_lists();
        self.layout.loading_level = false;
        // FreeAllLists' story FMV, restartingLevel = NO, InitLoadingScreen, StoryStartLevel.
        self.init_level_after_free();

        self.last_act_frame_count = 0;
        self.act_frame_count = 0;
        self.frame_count = 1;
        // TODO(port): InitTiming(60); StoryStartLevel() in story mode.
        // wave E: InitSpriteList
        self.sprite.init_sprite_list();
        // TODO(port): InitSpriteSortArray (renderer), InitSampleList, InitAmbientSoundList.

        // ------ Load data from disk ------------
        if let Some(f) = texture_bank_file(INGAMEGENERIC_TEX_BANK) {
            out.texture_banks.push(f);
        }
        // ambient: InitSampleList, InitAmbientSoundList, LoadSfx(worldID) (useAudio).
        self.pcaudio.init_sample_list();
        self.pcaudio.ambient_sound_list.clear();
        self.load_sfx(world, data);

        let wvd = self.layout.world_visual_data[world as usize];
        let lvd = wvd.level_visual_data[level as usize];

        // LoadMapBank(collBank) = LoadCollision + LoadScenics
        let coll = collision_file_for_coll_bank(lvd.coll_bank).ok_or_else(|| format!("collBank {} has no collision file", lvd.coll_bank))?;
        let bytes = data.read(coll).ok_or_else(|| format!("missing {coll}"))?;
        let c = level::Collision::parse(&bytes).map_err(|e| format!("{coll}: {e}"))?;
        self.map.load_collision(&c);
        out.collision_file = coll.to_string();

        let sce = scenics_file_for_coll_bank(lvd.coll_bank).ok_or_else(|| format!("collBank {} has no scenics file", lvd.coll_bank))?;
        let bytes = data.read(sce).ok_or_else(|| format!("missing {sce}"))?;
        let s = level::parse_scenics(&bytes).map_err(|e| format!("{sce}: {e}"))?;
        self.map.load_scenics(&s);
        out.scenics_file = sce.to_string();

        self.load_visual_banks_for_world(world, level, data, &mut out)?;

        // wave E: InitSpecFXList, InitParticleList, PTTextureLoad
        self.init_spec_fx_list();
        self.particle.init_particle_list();
        let banks: Vec<_> = out
            .texture_banks
            .iter()
            .filter_map(|f| data.read(f))
            .filter_map(|b| f2_formats::fla::maybe_decompress(b).ok())
            .filter_map(|b| f2_formats::texture::TexBank::parse(&b).ok())
            .collect();
        self.pt_texture_load(&banks);
        self.init_baby_list(true);
        self.init_enemy_linked_list();
        self.init_platform_linked_list();
        self.init_garib_list();
        self.init_trigger_list(); // wave D

        self.create_frogger(true, true);
        self.create_level_objects(world, level);

        self.init_tongues();

        self.frogger.fog.r = lvd.fog[0] as u8;
        self.frogger.fog.g = lvd.fog[1] as u8;
        self.frogger.fog.b = lvd.fog[2] as u8;
        self.frogger.fog.min = lvd.fog_near_dist as i16;
        self.frogger.fog.max = lvd.far_clip as i16;

        // LoadLevelEntities(worldVisualData[w].worldID, levelVisualData[l].levelID)
        let ent = entity_file_name(wvd.world_id, lvd.level_id);
        if let Some(bytes) = data.read(&ent) {
            match Entities::version(&bytes) {
                Some(v) if v == ENTITY_VERSION => {
                    let ents = Entities::parse(&bytes).map_err(|e| format!("{ent}: {e}"))?;
                    self.mem_load_entities(&ents);
                    self.level_files.entities = Some(ents);
                }
                v => self.effects.push(Effect::Log { text: format!("MemLoadEntities failed ({ent}: version {v:?})") }),
            }
        }

        // LoadLevelScript(worldVisualData[w].worldID, levelVisualData[l].levelID)
        let scr = script_file_name(wvd.world_id, lvd.level_id);
        match data.read(&scr) {
            Some(bytes) => match Script::parse(&bytes) {
                Ok(s) => self.level_files.script = Some(s),
                Err(e) => self.effects.push(Effect::Log { text: format!("InitLevelScript() failed: {scr}: {e}") }),
            },
            None => self.effects.push(Effect::Log { text: format!("error loading file {scr}") }),
        }
        // wave D: LoadLevelScript -> InitLevelScript
        if let Some(s) = self.level_files.script.clone() {
            self.init_level_script(s);
        }

        // LoadSfxMapping(worldID, levelID) - note: index ids, and after all actors of
        // InitLevel exist, so none of them get a mapping (sfx_anim_map was NULL).
        let sam = crate::general::sfx_mapping_file_name(world, level);
        if let Some(bytes) = data.read(&sam) {
            let (maps, amb) = level::parse_sfx_mapping(&bytes, self.map.tiles.len()).map_err(|e| format!("{sam}: {e}"))?;
            self.general.load_sfx_mapping(&maps, &amb);
            self.level_files.sfx_mapping = maps;
            // ambient: type 4 records -> AddAmbientSound(FindSample(s), &firstTile[uid].centre,
            // 12000, AMBIENT_VOLUME, -1, 0, 0, NULL), in file order.
            for t in self.general.ambient_tile_sfx.clone() {
                let centre = self.map.tiles.get(t.tile.0 as usize).map(|g| g.centre);
                self.add_ambient_sound(t.sample, centre, 12000, crate::pcaudio::AMBIENT_VOLUME as i16, -1, 0, 0, None);
            }
        }

        // wave E: InitInGameTextOverlays
        self.init_in_game_text_overlays(world, level);
        self.init_level_lives();
        self.frogger.player[0].spawn_timer = 0;
        self.frogger.player[0].spawn_score_level = 1;
        self.game.score_timer.init(90);
        if world == worldid::FRONTEND || self.game_state.multi != crate::define::SINGLEPLAYER {
            self.hide_level_counters(); // wave E
            if world == worldid::FRONTEND && level == LEVELID_FRONTEND1 {
                self.frogger.num_frogs = 1;
                self.game_state.multi = crate::define::SINGLEPLAYER;
            }
        }
        // TODO(port): InitTiming(60).
        self.act_frame_count = 0;
        // ambient: un_pause_audio (PrepareSong happens in init_level_finish)
        self.un_pause_audio();
        // drawLandscape, ScreenFade, InitTrainingMode (FRONTEND4) / train = 0, PrepareSong.
        // TODO(port): moolard cheat file.
        self.init_level_finish(world, level);
        self.frogger.player[0].old_lives = self.frogger.player[0].lives;
        self.game.start_cam = 1;
        self.game.end_level_timer.init(0);
        if self.game_state.multi != crate::define::SINGLEPLAYER {
            self.reinitialise_multiplayer();
            self.reset_multiplayer();
        }
        self.reset_camera(); // wave D
        self.init_camera();

        self.update_enemies();
        self.update_platforms();

        self.update_events(); // wave D

        Ok(out)
    }
}
